{
  "rule": "Start with the ball in the middle and a hidden orientation normal. Shake toggles the orientation; tilt left moves the ball one place left if normal and one place right if toggled, tilt right moves it one place right if normal and one place left if toggled, and the ball stops at the ends.",
  "commitments": [
    {
      "events": ["shake", "tilt left", "tilt left", "tilt left"],
      "predict": "right",
      "why": "If it did not end right, the idea that a shake reverses left tilts, so repeated left tilts push the ball right, would be wrong."
    },
    {
      "events": ["shake", "tilt right", "tilt right", "tilt right"],
      "predict": "left",
      "why": "If it did not end left, the symmetric claim that a shake reverses right tilts, so repeated right tilts push the ball left, would be wrong."
    },
    {
      "events": ["tilt left", "shake", "tilt left", "shake"],
      "predict": "middle",
      "why": "If it ended left, it would suggest shake does not flip the tilt direction or does not toggle back after two shakes."
    },
    {
      "events": ["tilt right", "shake", "tilt right", "shake"],
      "predict": "middle",
      "why": "If it ended right, it would cast doubt on shake toggling orientation for right tilts."
    },
    {
      "events": ["tilt left", "tilt left", "shake", "tilt right"],
      "predict": "left",
      "why": "If it ended middle, it would contradict that after a shake a right tilt pushes left from the left end."
    }
  ]
}

{
  "rule": "The ball starts in the middle. Tilt left/right normally move it one place left/right, but each shake toggles a hidden parity so that until the next shake, tilts are reversed; the ball stops at the ends.",
  "commitments": [
    {
      "events": ["shake", "tilt left"],
      "predict": "right",
      "why": "A rule without shake-reversal would predict left, so right is a strong test of the hidden parity."
    },
    {
      "events": ["shake", "tilt right"],
      "predict": "left",
      "why": "A rule without shake-reversal would predict right, so left is a strong test of the hidden parity."
    },
    {
      "events": ["shake", "tilt left", "shake", "tilt left"],
      "predict": "middle",
      "why": "If it came out right, the second shake would not be restoring the original tilt direction; this tests that shakes toggle parity rather than permanently reversing it."
    },
    {
      "events": ["tilt right", "shake", "tilt right"],
      "predict": "middle",
      "why": "If it came out right, tilt-right after a shake would not be reversed; the rule says it should move left from right to middle."
    },
    {
      "events": ["tilt left", "shake", "tilt right"],
      "predict": "left",
      "why": "If it came out middle or right, tilt-right after a shake would not be a leftward move, or the left boundary would not hold."
    }
  ]
}
